import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"三台·见梨花初带夜","description":"","frontmatter":{"title":"三台·见梨花初带夜","date":"2026-11-18T00:00:00.000Z","seq":269,"categories":["美文","宋词三百首"],"collection":"《宋词三百首》","tags":["宋词三百首","宋"],"poem":true,"poem_quote":false,"author":"万俟咏","source_book":"宋词三百首"},"headers":[],"relativePath":"blogs/宋词三百首/三台·见梨花初带夜.md","filePath":"blogs/宋词三百首/三台·见梨花初带夜.md"}'),o={name:"blogs/宋词三百首/三台·见梨花初带夜.md"};function l(c,a,n,_,m,r){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="三台·见梨花初带夜" tabindex="-1">三台·见梨花初带夜 <a class="header-anchor" href="#三台·见梨花初带夜" aria-label="Permalink to &quot;三台·见梨花初带夜&quot;">​</a></h1><p class="poem-meta">宋 · 万俟咏</p><div class="poem"><p class="poem-stanza">见梨花初带夜月，海棠半含朝雨。</p><p class="poem-stanza">内苑春、不禁过青门，御沟涨、潜通南浦。</p><p class="poem-stanza">东风静、细柳垂金缕。</p><p class="poem-stanza">望凤阙、非烟非雾。</p><p class="poem-stanza">好时代、朝野多欢，遍九陌、太平箫鼓。</p><p class="poem-stanza">乍莺儿百啭断续，燕子飞来飞去。</p><p class="poem-stanza">近绿水、台榭映秋千，斗草聚、双双游女。</p><p class="poem-stanza">饧香更、酒冷踏青路。</p><p class="poem-stanza">会暗识、夭桃朱户。</p><p class="poem-stanza">向晚骤、宝马雕鞍，醉襟惹、乱花飞絮。</p><p class="poem-stanza">正轻寒轻暖漏永，半阴半晴云暮。</p><p class="poem-stanza">禁火天、已是试新妆，岁华到、三分佳处。</p><p class="poem-stanza">清明看、汉宫传蜡炬。</p><p class="poem-stanza">散翠烟、飞入槐府。</p><p class="poem-stanza">敛兵卫、阊阖门开，住传宣、又还休务。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
